static const char * const prof_kind[PROF_NODES] = { "-", "UrsaConv2d", "-", "-", "UrsaConv2d", "UrsaConv2d", "UrsaResAdd", "-", "UrsaConv2d", "UrsaConv2d", "UrsaResAdd", "-", "-", "UrsaConv2d", "UrsaConv2d", "-", "UrsaConv2d", "UrsaResAdd", "-", "UrsaConv2d", "UrsaConv2d", "UrsaResAdd", "-", "-", "UrsaConv2d", "UrsaConv2d", "-", "UrsaConv2d", "UrsaResAdd", "-", "UrsaConv2d", "UrsaConv2d", "UrsaResAdd", "-", "-", "UrsaConv2d", "UrsaConv2d", "-", "UrsaConv2d", "UrsaResAdd", "-", "UrsaConv2d", "UrsaConv2d", "UrsaResAdd", "UrsaAdaptiveAvgPool", "UrsaLinear" };
