static const int prof_depth[PROF_NODES] = { 0, 1, 1, 2, 3, 3, 3, 2, 3, 3, 3, 1, 2, 3, 3, 3, 4, 3, 2, 3, 3, 3, 1, 2, 3, 3, 3, 4, 3, 2, 3, 3, 3, 1, 2, 3, 3, 3, 4, 3, 2, 3, 3, 3, 1, 1 };
